function useEvidenceInbox(tick:number){
 const [items,setItems]=useState<Data[]>([]),[error,setError]=useState(''),[retry,setRetry]=useState(0);
 useEffect(()=>{let alive=true;let timer:ReturnType<typeof setTimeout>;
  const poll=async()=>{try{const data=await api('/evidence');if(alive){setItems(data);setError('')}}catch{if(alive)setError('截图列表刷新失败，正在自动重试。')}finally{if(alive)timer=setTimeout(poll,2000)}};
  void poll();return()=>{alive=false;clearTimeout(timer)};
 },[tick,retry]);
 return {items,error,refresh:()=>setRetry(n=>n+1)};
}
function BatchProgress({job}:{job:Data}){
 const p=job.progress;if(!p)return null;const active=['queued','running','cancelling'].includes(job.state);
 const eta=p.eta_seconds==null?(job.state==='queued'?'排队中，开始后估算剩余时间':active?'正在估算剩余时间':''):(p.eta_initial?'初步预计剩余约 ':'预计剩余约 ')+Math.max(1,Math.ceil(p.eta_seconds/60))+' 分钟';
 return <section className="batch-progress" aria-label="更新进度"><div className="between"><h3>{active?'正在更新':'更新结果'} · {names[p.platform]}</h3><Pill>{states[job.state]||job.state}</Pill></div><progress max={p.total||1} value={p.done}/><p role="status">已处理 {p.done} / {p.total} 张 · 已更新 {p.updated} 张{p.attention>0?' · '+p.attention+' 张需补充截图':''}</p><small>{p.stage}{p.stage&&eta?' · ':''}{eta}{active&&'（随处理速度调整）'}</small>{job.error&&<p className="red">{job.error}</p>}{job.next_retry_at&&<p>额度恢复后重试：{date(job.next_retry_at)}</p>}{p.items?.length>0&&<details><summary>查看每张截图的结果</summary>{p.items.map((item:Data,i:number)=><div className="batch-item" key={item.evidence_id}><img src={'/api/evidence/'+item.evidence_id+'/image'} alt={'处理截图 '+(i+1)}/><div><strong>{item.stage}</strong>{item.result?.updated?.map((r:Data,k:number)=><p key={k}>{r.title} · 已更新 {Object.keys(r.metrics).length} 项数据</p>)}{item.result?.reasons?.map((r:string,k:number)=><p className="red" key={k}>{r}</p>)}</div></div>)}</details>}</section>
}
function SearchablePostPicker({options,value,onChange,disabled}:{options:Data[],value:string,onChange:(key:string)=>void,disabled:boolean}){
 const [query,setQuery]=useState(''),[open,setOpen]=useState(false),[focusIndex,setFocusIndex]=useState(0);
 const selected=options.find(x=>x.key===value);
 const matches=options.filter(x=>x.label.toLocaleLowerCase().includes(query.trim().toLocaleLowerCase())).slice(0,100);
 const choose=(key:string)=>{onChange(key);setQuery('');setOpen(false)};
 return <div className="post-picker"><input role="combobox" aria-label="搜索作品" aria-expanded={open} aria-controls="post-picker-options" aria-autocomplete="list" placeholder="输入标题关键字搜索" value={open?query:selected?.label||''} disabled={disabled} onFocus={()=>{setOpen(true);setQuery('');setFocusIndex(0)}} onBlur={()=>setTimeout(()=>setOpen(false),120)} onChange={e=>{setQuery(e.target.value);setFocusIndex(0);onChange('');setOpen(true)}} onKeyDown={e=>{if(e.key==='Escape')setOpen(false);if(e.key==='ArrowDown'){e.preventDefault();setFocusIndex(i=>Math.min(i+1,matches.length-1))}if(e.key==='ArrowUp'){e.preventDefault();setFocusIndex(i=>Math.max(0,i-1))}if(e.key==='Enter'&&open&&matches[focusIndex]){e.preventDefault();choose(matches[focusIndex].key)}}}/>{open&&<div id="post-picker-options" className="post-picker-options" role="listbox">{matches.length?matches.map((item:Data,index:number)=><button type="button" role="option" aria-selected={item.key===value} className={'post-picker-option'+(index===focusIndex?' focused':'')} key={item.key} onMouseDown={e=>{e.preventDefault();choose(item.key)}}><span>{item.title}</span><small>{item.published_local_date||'发布时间待确认'}</small></button>):<p className="muted">没有找到匹配的作品，请先在我的创作中自动拉取帖子。</p>}</div>}</div>;
}
function UpdateModal(s:Shared&{close:()=>void,targetPublicationId?:string|null}){
 const {items:evidence,error:inboxError,refresh:refreshInbox}=useEvidenceInbox(s.tick);
 const {data:publications}=useData('/publications',s.tick);
 const [platform,setPlatform]=useState(''),[mode,setMode]=useState(s.targetPublicationId?'single':'all'),[publicationId,setPublicationId]=useState(s.targetPublicationId||''),[excluded,setExcluded]=useState<string[]>([]),[included,setIncluded]=useState<string[]>([]),[busy,setBusy]=useState(false);
 useEffect(()=>{if(s.targetPublicationId&&publications){const target=publications.find((x:Data)=>x.id===s.targetPublicationId);if(target)setPlatform(target.platform)}},[s.targetPublicationId,publications]);
 const postOptions=(publications||[]).filter((post:Data)=>!platform||post.platform===platform).map((post:Data)=>({key:post.id,title:post.title,label:post.title+' · '+(post.published_local_date||'发布时间待确认'),published_local_date:post.published_local_date}));
 const targetKey=publicationId||'';
 const chooseTarget=(key:string)=>setPublicationId(key);
 const available=evidence.filter(x=>!x.updated_platform),selected=available.filter(x=>mode==='single'?included.includes(x.id):!excluded.includes(x.id));
 const activeBatch=s.jobs.find(j=>j.type==='screenshot_batch'&&['queued','running','cancelling','waiting_quota','waiting_auth','recovery_required','blocked_config'].includes(j.state));
 const batch=activeBatch||s.jobs.find(j=>j.type==='screenshot_batch'&&j.progress?.items?.some((item:Data)=>evidence.some(x=>x.id===item.evidence_id)));
 const active=!!activeBatch;
 const upload=async(e:React.ChangeEvent<HTMLInputElement>)=>{const files=Array.from(e.target.files||[]);setBusy(true);try{for(const file of files){const body=new FormData();body.append('file',file);await s.act(()=>api('/updates/screenshots','POST',body))}s.notify('截图已接收，点击确认更新即可自动识别')}catch{}finally{setBusy(false);e.target.value=''}};
 const start=async()=>{setBusy(true);try{await s.act(()=>api('/updates/batch','POST',{platform,evidence_ids:selected.map(x=>x.id),publication_id:mode==='single'?publicationId:null}),'已开始识别并更新，可在更新进度或任务记录中查看')}catch{}finally{setBusy(false)}};
 const reset=async()=>{if(!window.confirm('清空本弹框的选择和历史上传列表？已用于指标的截图仍保留为数据凭证，已保存的指标不会删除。'))return;setBusy(true);try{const result=await s.act(()=>api('/updates/screenshots/clear','POST',{}));setPlatform('');setMode('all');setPublicationId('');setExcluded([]);setIncluded([]);s.openUpdate();refreshInbox();s.notify('表单已重置，上传列表已清空 '+result.cleared+' 张')}catch{}finally{setBusy(false)}};
 return <Modal title="更新数据" close={s.close} wide><div className="modal-body"><div className="update-steps">选择平台 → 选择更新范围 → 上传后台截图 → 确认更新</div><Field label="截图所属平台"><select value={platform} disabled={busy||active} onChange={e=>{setPlatform(e.target.value);setPublicationId('');setIncluded([])}}><option value="">请选择平台</option><option value="xiaohongshu">小红书</option><option value="douyin">抖音</option></select></Field><div className="two-fields"><Field label="更新范围"><select aria-label="更新范围" value={mode} disabled={busy||active} onChange={e=>{setMode(e.target.value);setPublicationId('');setIncluded([])}}><option value="all">自动匹配多篇</option><option value="single">指定单篇作品</option></select></Field>{mode==='single'&&<div className="field"><span>选择作品</span><SearchablePostPicker options={postOptions} value={targetKey} onChange={chooseTarget} disabled={busy||active||!platform}/></div>}</div>{mode==='single'&&<p className="muted">可搜索自动拉取的平台作品。选定单篇后，识别出的数字直接更新这篇作品；不要求截图显示标题，也不按周期口径拦截。</p>}<div className="upload-box"><Upload size={28}/><h3>上传该平台的后台截图</h3><p>可一次上传多张；指定单篇时直接更新所选作品。</p><label className="btn primary">{busy?'处理中…':'选择截图'}<input type="file" hidden accept="image/png,image/jpeg,image/webp" multiple disabled={busy||active} onChange={upload}/></label><small>PNG / JPG / WebP，每张不超过20MB</small></div><details className="phone-upload-option"><summary>用手机扫码上传</summary><PhoneUpload {...s}/></details><section className="evidence-inbox" aria-label="收到的截图"><div className="between"><h3 role="status">已收到 {evidence.length} 张截图</h3><button className="btn small" onClick={refreshInbox}>刷新截图</button></div><small>本次选择 {selected.length} 张；单篇模式请只勾选该篇对应截图。已更新图片不会重复处理。</small>{inboxError&&<p role="alert" className="red">{inboxError}</p>}<div className="evidence-thumbnails">{evidence.map((x:Data,i:number)=><label key={x.id} className={'evidence-thumbnail'+((mode==='single'?included.includes(x.id):!excluded.includes(x.id))&&!x.updated_platform?' selected':'')}><input type="checkbox" aria-label={'选择截图 '+(i+1)} checked={(mode==='single'?included.includes(x.id):!excluded.includes(x.id))&&!x.updated_platform} disabled={busy||active||!!x.updated_platform} onChange={e=>mode==='single'?setIncluded(old=>e.target.checked?[...old,x.id]:old.filter(id=>id!==x.id)):setExcluded(old=>e.target.checked?old.filter(id=>id!==x.id):[...old,x.id])}/><img loading="lazy" src={'/api/evidence/'+x.id+'/image'} alt={'截图 '+(i+1)}/><span>{x.updated_platform?names[x.updated_platform]+' · 已更新':date(x.received_at)}</span></label>)}</div></section>{batch&&<><BatchProgress job={batch}/>{['failed','partial','interrupted','waiting_auth','waiting_quota','blocked_config','needs_model_selection'].includes(batch.state)&&<button className="btn" onClick={()=>s.act(()=>api('/jobs/'+batch.id+'/retry','POST'),'已重试未完成部分').catch(()=>{})}>重试未完成部分</button>}</>}<p className="muted">确认后使用腾讯云OCR和当前模型自动识别并更新，按已配置服务计费。缺失或无法辨认的数字不补零，并显示原因。</p></div><div className="modal-footer"><button className="btn" disabled={busy||active} onClick={reset}>重置并清空截图</button><button className="btn" onClick={s.close}>{active?'后台继续，关闭':'关闭'}</button><button className="btn primary" disabled={!platform||!selected.length||(mode==='single'&&!targetKey)||busy||active} onClick={start}>{active?'更新中…':'确认更新'+(selected.length?'（'+selected.length+'张）':'')}</button></div></Modal>;
}

function GrowthChart({accounts,start,end}:{accounts:Data[],start:string,end:string}){
 const colors=['#d83d4c','#8d9bb2'];const days=Math.round((new Date(end).getTime()-new Date(start).getTime())/86400000);
 const series=accounts.map(a=>{const points:Data={};a.points.forEach((p:Data)=>points[p.local_date]=p.value);return Array.from({length:days},(_,i)=>{const before=new Date(new Date(start).getTime()+i*86400000).toISOString().slice(0,10);const after=new Date(new Date(start).getTime()+(i+1)*86400000).toISOString().slice(0,10);return points[before]!=null&&points[after]!=null?points[after]-points[before]:null})});
 const values=series.flat().filter((x):x is number=>x!==null);if(!values.length)return <div className="chart-empty"><TrendingUp size={32}/><p>补齐账号截图后，在这里查看真实增长</p><small>缺失的观测值保留未知</small></div>;
 const min=Math.min(0,...values),max=Math.max(1,...values),y=(v:number)=>155-(v-min)/(max-min)*130,x=(i:number)=>35+i*500/Math.max(1,days-1);
 return <div className="growth-chart"><svg viewBox="0 0 570 190" role="img" aria-label="每日净涨粉趋势，缺测处断开"><line x1="30" y1={y(0)} x2="545" y2={y(0)} stroke="#e6e9ee"/>{series.map((points,si)=><g key={si}>{points.map((v,i)=>v===null?null:<g key={i}>{i>0&&points[i-1]!==null&&<line x1={x(i-1)} y1={y(points[i-1] as number)} x2={x(i)} y2={y(v)} stroke={colors[si]} strokeWidth="2"/>}<circle cx={x(i)} cy={y(v)} r="3" fill={colors[si]}><title>{names[accounts[si].platform]}：{v}</title></circle></g>)}</g>)}<text x="30" y="183" fill="#9ca4b0" fontSize="11">{start}</text><text x="545" textAnchor="end" y="183" fill="#9ca4b0" fontSize="11">{end}</text></svg><small>红色：小红书　灰色：抖音 · 缺测处不连线</small></div>
}
