 return <section className="form-card"><h3>平台发布资料</h3>{publication.canonical_url&&<a className="text-link" href={publication.canonical_url} target="_blank" rel="noreferrer">打开平台作品 <ArrowUpRight size={14}/></a>}<small>最近指标观测：{date(publication.metrics?.observed_at)}</small><Field label="平台标题（留空使用同步标题）"><input value={form.title} onChange={e=>setForm({...form,title:e.target.value})}/></Field><Field label="平台正文（留空使用同步正文）"><textarea value={form.body_text} onChange={e=>setForm({...form,body_text:e.target.value})}/></Field><Field label="投流状态"><select value={form.paid_status} onChange={e=>setForm({...form,paid_status:e.target.value})}><option value="unknown">未知</option><option value="organic">自然流量</option><option value="paid">有投流</option></select></Field><button className="btn primary" onClick={()=>s.act(()=>api('/publications/'+publication.id,'PATCH',{...form,expected_version:publication.version}),'平台资料已保存').then(close).catch(()=>{})}>保存平台资料</button></section>
