function HotTopics(s:Shared){
 const {data,error}=useData('/hot-topics',s.tick);
 const [platform,setPlatform]=useState('douyin');
 const activeStates=['queued','running','waiting_auth','waiting_quota','recovery_required'];
 const active=s.jobs.find(job=>job.type==='hot_topics'&&activeStates.includes(job.state))||data?.active_job;
 const board=data?.platforms?.find((item:Data)=>item.platform===platform);
 return <><Heading title="热点选题" description="按账号画像的关注领域，筛选近7天图文与视频内容；每个领域最多3条，总计最多20条。"><button className="btn primary" disabled={!!active} onClick={()=>s.act(()=>api('/hot-topics/refresh','POST'), '热点选题更新已开始').catch(()=>{})}><RefreshCw className={active?'spin':''} size={16}/>{active?'更新中…':'立即更新'}</button></Heading><div className="hot-topic-meta"><span><Clock size={15}/>每天 09:00 自动更新</span><span>更新过程中不可重复提交</span><a href="#profile">管理关注领域 <ChevronRight size={14}/></a></div>{data?<><div className="tabs hot-topic-tabs">{[['douyin','抖音'],['bilibili','B站'],['zhihu','知乎'],['xiaohongshu','小红书']].map(([key,label])=><button key={key} className={platform===key?'active':''} onClick={()=>setPlatform(key)}>{label}<small>{data.platforms.find((item:Data)=>item.platform===key)?.items?.length||0}</small></button>)}</div>{board&&<><div className="hot-topic-keywords">{board.keywords?.map((keyword:string)=><span key={keyword}>{keyword}({board.keyword_counts?.[keyword]||0})</span>)}</div><HotTopicBoard s={s} board={board}/></>}</>:<Load error={error}/>}</>;
}

createRoot(document.getElementById('root')!).render(<App/>);
